/* Presentation-quality 3D renders are separate from orbitable schematic geometry. */
let packagingVisualMode='rendered';
const machineArt=[{src:'assets/packaging-line-1.png',name:'Tablet blister packaging machine',stations:[[10,25],[43,12],[65,20],[87,36]]},{src:'assets/packaging-line-2.png',name:'Capsule cartoning machine',stations:[[9,25],[43,15],[65,22],[88,39]]},{src:'assets/packaging-line-3.png',name:'Sterile vial filling and capping machine',stations:[[10,34],[43,13],[64,22],[88,36]]}];
const engineeringModelSlot=modelSlot;
modelSlot=function(kind,index=0,large=false){if(kind!=='packaging'||large&&packagingVisualMode==='engineering')return engineeringModelSlot(kind,index,large);const art=machineArt[index],stationNames=index===2?['Vial feed','Filling','Inspection','Capping']:index===1?['Carton feed','Folding','Inspection','Cartoning']:['Feeder','Sealing','Inspection','Outfeed'];return `<figure class="rendered-equipment ${large?'rendered-equipment-large':'rendered-equipment-card'}" data-render-line="${index}" aria-label="${art.name}"><img src="${art.src}" alt="Photorealistic 3D render of a ${art.name.toLowerCase()} with stainless steel cabinets, transparent safety guards, conveyor and touch panel" width="1536" height="1024" decoding="async" ${large?'fetchpriority="high"':''}>${large?`<div class="equipment-hotspots">${art.stations.map((p,i)=>`<button class="equipment-hotspot" style="left:${p[0]}%;top:${p[1]}%" onclick="packStation(${i})" aria-label="Inspect ${stationNames[i]}"><span>${stationNames[i]}</span><i></i></button>`).join('')}</div><div class="equipment-render-caption">Illustrative equipment render · Select a station for details</div>`:''}</figure>`};
function switchPackagingVisual(mode){if(!['rendered','engineering'].includes(mode))return;packagingVisualMode=mode;render()}
packStation=function(i){const names=state.line===2?['Vial feed','Filling','Inspection','Capping']:state.line===1?['Carton feed','Folding','Inspection','Cartoning']:['Feeder','Sealing','Inspection','Outfeed'],descriptions=state.line===2?['Vial supply is ready for the selected batch.','Filling heads and transfer tubing are represented in the equipment render.','Inspect sample acceptance and reject trends before release.','Capping and labeling readiness supports downstream dispatch.']:state.line===1?['Carton stock and magazine readiness support the current order.','Folding and packing are constrained during the planned changeover.','Review package completeness and quality exceptions.','Finished cartons are handed over to dispatch.']:['Material supply is sufficient for the current batch.','Review sealing readiness and any open quality hold.','Inspect presentation, completeness and rejected units.','Completed blister packs are handed over to the next stage.'];openModal(names[i]+' · Line '+(state.line+1),`<p>${descriptions[i]}</p><div class="modal-metrics"><div><small>Line state</small><h3>${lineData(state.line).status}</h3></div><div><small>Line utilization</small><h3>${lineData(state.line).utilization}%</h3></div></div><div class="actions">${opButton('Station documents',"documentCenter('Packaging')")}${opButton('Related alarms','alarmCenter()')}</div>`)};
function openEquipmentRender(){const art=machineArt[state.line];openModal(art.name,`<div class="render-inspection"><img src="${art.src}" alt="Detailed equipment render: ${art.name}"></div><div class="scope-label">Illustrative 3D-rendered equipment · Line ${state.line+1} · ${lineSpecs[state.line].product}</div><div class="actions">${opButton('Open engineering model',"$('#modal').close();switchPackagingVisual('engineering')")}${opButton('Equipment documents',"documentCenter('Packaging')")}</div>`);$('#modal').classList.add('wide-modal','equipment-modal')}
const packagingBeforeRealistic=packagingView;packagingView=function(){let html=packagingBeforeRealistic();const toolbar=`<div class="equipment-view-toolbar"><span>${packagingVisualMode==='rendered'?'REALISTIC EQUIPMENT VIEW':'ORBITABLE ENGINEERING MODEL'}</span><div class="equipment-view-switch">${opButton('Rendered view',"switchPackagingVisual('rendered')",packagingVisualMode==='rendered'?'active':'')}${opButton('Explore 3D',"switchPackagingVisual('engineering')",packagingVisualMode==='engineering'?'active':'')}${opButton('Enlarge',"openEquipmentRender()")}</div></div>`;html=html.replace('<div class="station-buttons">',toolbar+'<div class="station-buttons">');html=html.replace('Models are illustrative, unbranded 3D equipment.','Detailed equipment renders are illustrative and unbranded. Use Explore 3D for the rotatable engineering model.');return html};
render();
